import sys

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]

    size = 1 << N
    alphabet = "abcdefghijklmnopqrstuvwxyz"

    # Each LCS DP row is determined by its bitmask:
    # bit j is 1 iff row[j+1] > row[j].
    rows = []
    for mask in range(size):
        row = [0] * (N + 1)
        cur = 0
        for j in range(1, N + 1):
            if (mask >> (j - 1)) & 1:
                cur += 1
            row[j] = cur
        rows.append(row)

    # Precompute transitions: mask -> list of (next_mask, number_of_chars)
    trans = []
    for mask in range(size):
        a = rows[mask]
        d = {}
        for c in alphabet:
            bprev = 0
            nmask = 0
            for j in range(1, N + 1):
                if S[j - 1] == c:
                    b = a[j - 1] + 1
                    if a[j] > b:
                        b = a[j]
                    if bprev > b:
                        b = bprev
                else:
                    b = a[j] if a[j] >= bprev else bprev

                if b > bprev:
                    nmask |= 1 << (j - 1)
                bprev = b

            d[nmask] = d.get(nmask, 0) + 1
        trans.append(list(d.items()))

    # popcount for masks
    pop = [0] * size
    for mask in range(1, size):
        pop[mask] = pop[mask >> 1] + (mask & 1)

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size
        for mask, val in enumerate(dp):
            if val:
                for nmask, mult in trans[mask]:
                    ndp[nmask] += val * mult
        for i in range(size):
            ndp[i] %= MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        ans[pop[mask]] += val

    ans = [x % MOD for x in ans]
    print(" ".join(map(str, ans)))

if __name__ == "__main__":
    main()
