import math


def icbrt(n):
    """Return the largest integer r such that r^3 <= n."""
    if n <= 0:
        return 0
    lo, hi = 0, 1
    while hi * hi * hi <= n:
        hi *= 2
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if mid * mid * mid <= n:
            lo = mid
        else:
            hi = mid
    return lo


def main():
    data = sys.stdin.read().strip()
    if not data:
        return

    N = int(data)

    # Let d = x - y. Then N = d * (3y^2 + 3dy + d^2).
    # Since y >= 1, N > d^3, so d^3 < N.
    limit = icbrt(N - 1)

    for d in range(1, limit + 1):
        if N % d != 0:
            continue

        m = N // d
        # (6y + 3d)^2 = 12m - 3d^2
        D = 12 * m - 3 * d * d
        if D <= 0:
            continue

        s = math.isqrt(D)
        if s * s != D:
            continue

        t = s - 3 * d
        if t > 0 and t % 6 == 0:
            y = t // 6
            x = y + d
            if x * x * x - y * y * y == N:
                print(x, y)
                return

    print(-1)


