import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    idx = 1
    dice = []

    for _ in range(n):
        k = data[idx]
        idx += 1
        cnt = {}
        for _ in range(k):
            a = data[idx]
            idx += 1
            cnt[a] = cnt.get(a, 0) + 1
        dice.append((k, cnt))

    # Iterate over the smaller distinct-face dictionary for each pair.
    dice.sort(key=lambda x: len(x[1]))

    ans = 0.0

    for i in range(n):
        ki, ci = dice[i]
        for j in range(i + 1, n):
            kj, cj = dice[j]

            get = cj.get
            dot = 0

            for value, count in ci.items():
                other = get(value)
                if other is not None:
                    dot += count * other

            prob = dot / (ki * kj)
            if prob > ans:
                ans = prob

    print(f"{ans:.15f}")

if __name__ == "__main__":
    main()

