        adj[v].append((u, w))

    target = N - 1
    ans = (1 << 61) - 1

    def dfs(v, xor_value, visited_mask):
        nonlocal ans

        if ans == 0:
            return

        if v == target:
            if xor_value < ans:
                ans = xor_value
            return

        for to, w in adj[v]:
            if not (visited_mask >> to) & 1:
                dfs(to, xor_value ^ w, visited_mask | (1 << to))

    dfs(0, 0, 1)
    print(ans)

